const fs = require("fs");
const path = require("path");

// ORCALY_PARTNER_ACADEMY_V3_INSTALLER

const root = process.cwd();

function readNormalized(rel) {
  const file = path.join(root, rel);
  if (!fs.existsSync(file)) {
    throw new Error(`Arquivo nao encontrado: ${rel}`);
  }

  const raw = fs.readFileSync(file, "utf8");

  return {
    file,
    eol: raw.includes("\r\n") ? "\r\n" : "\n",
    text: raw.replace(/\r\n/g, "\n"),
  };
}

function outputWithEol(text, eol) {
  return eol === "\r\n"
    ? text.replace(/\n/g, "\r\n")
    : text;
}

const page = readNormalized(
  "app/parceiros/painel/page.tsx",
);

const replacements = [
  {
    search:
      'import PartnerCoursesTab from "@/components/parceiros/PartnerCoursesTab";',
    replacement:
      'import PartnerAcademyV3 from "@/components/parceiros/PartnerAcademyV3";',
    label: "import da academia",
  },
  {
    search:
      '["courses", "Cursos"],',
    replacement:
      '["courses", "Academia"],',
    label: "nome da aba",
  },
  {
    search:
      '{tab === "courses" ? (\n            <PartnerCoursesTab />\n          ) : null}',
    replacement:
      '{tab === "courses" ? (\n            <PartnerAcademyV3 partnerName={dashboard.profile.name} />\n          ) : null}',
    label: "render da academia",
  },
];

let nextPage = page.text;

for (const item of replacements) {
  const first = nextPage.indexOf(
    item.search,
  );

  if (first === -1) {
    if (
      nextPage.includes(
        item.replacement,
      )
    ) {
      continue;
    }

    throw new Error(
      `Trecho nao encontrado: ${item.label}`,
    );
  }

  const second = nextPage.indexOf(
    item.search,
    first + item.search.length,
  );

  if (second !== -1) {
    throw new Error(
      `Trecho duplicado: ${item.label}`,
    );
  }

  nextPage =
    nextPage.slice(0, first) +
    item.replacement +
    nextPage.slice(
      first + item.search.length,
    );
}

